local LuaType = require(script.Parent.LuaType)

return function()
	describe("LuaType", function()
		it("应该正确创建一个新的LuaType实例", function()
			local config = {
				FilePath = "test/path",
				Parameters = { "param1", "param2" },
				Name = "testKey",
				Context = "testContext",
				Ctor = "testCtor",
				IsOperation = true,
			}

			local luaType = LuaType.new("", config)

			expect(luaType.__FilePath).to.equal(config.FilePath)
			expect(luaType.__Parameters).to.equal(config.Parameters)
			expect(luaType.Name).to.equal(config.Name)
			expect(luaType.__Context).to.equal(config.Context)
			expect(luaType.__Ctor).to.equal(config.Ctor)
			expect(luaType.__IsOperation).to.equal(config.IsOperation)
		end)

		it("应该正确解析参数", function()
			local config = {
				FilePath = "test/path",
				Parameters = { "param1", "param2" },
			}

			local luaType = LuaType.new("", config)

			expect(#luaType.__ParsedParameters).to.equal(2)
			expect(luaType.__ParsedParameters[1].ParameterType.FullName).to.equal("param1")
			expect(luaType.__ParsedParameters[2].ParameterType.FullName).to.equal("param2")
		end)

		it("GetConstructors应该返回包含GetParameters函数的表", function()
			local luaType = LuaType.new("", { FilePath = "test/path", Parameters = {} })

			local constructors = luaType:GetConstructors()

			expect(type(constructors[1].GetParameters)).to.equal("function")
			expect(#constructors[1].GetParameters()).to.equal(0)
		end)

		it("GetGenericArguments应该抛出'未实现'错误", function()
			local luaType = LuaType.new("", { FilePath = "test/path", Parameters = {} })

			expect(function()
				luaType:GetGenericArguments()
			end).to.throw("未实现")
		end)
	end)
end
